    /**
     * Method to retrieve the Contact via an ContactPrimaryKey.
     * @param 	id Long
     * @return 	Contact
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Contact handle( FindContactQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getContactId() );
    }
    
    /**
     * Method to retrieve a collection of all Contacts
     *
     * @param	query	FindAllContactQuery 
     * @return 	List<Contact> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Contact> handle( FindAllContactQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindContact,
 * but only if the id matches
 *
 * @param		entity	Contact
 */
	protected void emitFindContact( Contact entity ) {
		LOGGER.info("handling emitFindContact" );
		
	    queryUpdateEmitter.emit(FindContactQuery.class,
	                            query -> query.getFilter().getContactId().equals(entity.getContactId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllContact
	 * 
	 * @param		entity	Contact
	 */
	protected void emitFindAllContact( Contact entity ) {
		LOGGER.info("handling emitFindAllContact" );
		
	    queryUpdateEmitter.emit(FindAllContactQuery.class,
	                            query -> true,
	                            entity);
	}

